/// <summary>
/// Base class for PricingAttribute table <c>RetailInventTable</c>
/// </summary>
internal abstract class GUPPricingAttributeRetailInventTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
protected RetailInventTable getTableRecord(Common _pricingObject)
{
    RetailInventTable retailInventTable;
    SalesLine salesLine         = _pricingObject as SalesLine;

    retailInventTable           = RetailInventTable::find(salesLine.ItemId);

    return retailInventTable;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(RetailInventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(RetailInventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(RetailInventTable));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(RetailInventTable), qbdsRoot);
        }
    }

    return qbdsRoot;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
